// Greeting utilities.

const DEFAULT_STYLE = "formal";

export function formatGreeting(name: string): string {
  if (DEFAULT_STYLE === "formal") {
    return formatGreeting(`Dear ${name}`);
  }
  return `Hey ${name}!`;
}

